نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
زنجیرهٔ انقضای «لبنیات» را باز کن و راه‌حل بده. (یاس فروشگاه‌ها)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "expiry_report",
      "description": "ارزش کالای نزدیک انقضا",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "exp_value_m",
        "exp_days"
      ]
    },
    {
      "dataset": "demand_forecast",
      "description": "پیش‌بینی و فروش واقعی هر دسته و هفته",
      "dimensions": [
        "category",
        "week"
      ],
      "measures": [
        "forecast_units",
        "actual_units"
      ]
    },
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "expiry_rate",
      "description": "نرخ کالای نزدیک انقضا",
      "formula": "ارزش نزدیک انقضا تقسیم بر موجودی کل",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "forecast_accuracy",
      "description": "دقت پیش‌بینی تقاضا",
      "formula": "یک منهای قدرمطلق خطا تقسیم بر واقعی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سقف پوشش موجودی دسته‌های فاسدشدنی هفت روز",
    "سفارش‌گذاری روزانه از مرکز توزیع",
    "کمپین‌های تخفیف ماهانه بر تقاضا اثر می‌گذارد"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "expiry_report",
    "filters": {
      "category": "لبنیات",
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "exp_value_m": 1025,
  "share_of_waste_pct": 4.4,
  "top_branch": "شعبهٔ ۳"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "demand_forecast",
    "filters": {
      "category": "لبنیات",
      "period": "last_8_weeks"
    }
  }
}

TOOL_OBSERVATION:
{
  "mean_bias_pct": -28,
  "note": "پیش‌بینی پیوسته بالاتر از فروش واقعی است"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "category": "لبنیات",
      "branch": "شعبهٔ ۳"
    }
  }
}

TOOL_OBSERVATION:
{
  "days_cover": 22,
  "oos_rate_pct": 6.2,
  "note": "هم‌زمان پوشش بالا و نبودِ کالاهای پرفروش — سبد نامتوازن"
}

نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
جمع‌بندی موجودی برای مدیرعامل + برنامهٔ سی‌روزه. (مارکت دی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    },
    {
      "dataset": "expiry_report",
      "description": "ارزش کالای نزدیک انقضا",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "exp_value_m",
        "exp_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "expiry_rate",
      "description": "نرخ کالای نزدیک انقضا",
      "formula": "ارزش نزدیک انقضا تقسیم بر موجودی کل",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "oos_rate",
      "description": "نرخ نبود کالا در قفسه",
      "formula": "رخداد قفسهٔ خالی تقسیم بر بازرسی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است",
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "سفارش‌گذاری روزانه از مرکز توزیع"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "period": "today",
      "view": "aggregate"
    }
  }
}

TOOL_OBSERVATION:
{
  "total_stock_m": 85500,
  "avg_days_cover": 24
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "expiry_report",
    "filters": {
      "period": "curr_month",
      "view": "aggregate"
    }
  }
}

TOOL_OBSERVATION:
{
  "near_expiry_m": 2400
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "oos_rate"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "oos_rate_pct": 3.4
}

