      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    },
    {
      "dataset": "shrinkage_log",
      "description": "کسری و مفقودی انبار",
      "dimensions": [
        "branch",
        "month"
      ],
      "measures": [
        "loss_m"
      ]
    }
