TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "shrinkage_log",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "holding_cost_pct_month": {
    "centralized": 0.64,
    "branch_based": 0.97
  },
  "note": "هزینهٔ نگهداری شعبه شامل فضا، خرابی و کسری است"
}

