نقش سازمانی: inventory_planning_manager (inventory_planning_manager)

درخواست کاربر:
چرا سیستم تقاضا را اشتباه می‌خواند؟ عدد بده. (زنجیرهٔ شهروند)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "demand_forecast",
      "description": "پیش‌بینی و فروش واقعی هر دسته و هفته",
      "dimensions": [
        "category",
        "week"
      ],
      "measures": [
        "forecast_units",
        "actual_units"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "forecast_accuracy",
      "description": "دقت پیش‌بینی تقاضا",
      "formula": "یک منهای قدرمطلق خطا تقسیم بر واقعی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز و انبار شعبه",
    "سفارش‌گذاری روزانه از مرکز توزیع",
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "forecast_accuracy"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "forecast_accuracy_pct": {
    "prev": 84.7,
    "curr": 78.3,
    "change_pp": -6.4
  },
  "category": "نوشیدنی"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "demand_forecast",
    "filters": {
      "category": "نوشیدنی",
      "period": "curr_month"
    }
  }
}

