سیاست پوشش این دو دسته باید یکی باشد؟ (زنجیرهٔ اتکا)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "stock_turnover",
      "description": "گردش موجودی",
      "formula": "فروش دوره تقسیم بر میانگین موجودی",
      "unit": "بار",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "کمپین‌های تخفیف ماهانه بر تقاضا اثر می‌گذارد",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز و انبار شعبه",
    "سفارش‌گذاری روزانه از مرکز توزیع"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "category": [
        "شوینده و بهداشتی",
        "سرمودی و فریزری"
      ],
      "period": "today"
    }
  }
}

