موجودی «کنسرو و غذای آماده» را متمرکز کنیم یا در شعبه‌ها پخش؟ عدد بده. (مدیر موجودی — زنجیرهٔ اتکا)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    },
    {
      "dataset": "shrinkage_log",
      "description": "کسری و مفقودی انبار",
      "dimensions": [
        "branch",
        "month"
      ],
      "measures": [
        "loss_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "oos_rate",
      "description": "نرخ نبود کالا در قفسه",
      "formula": "رخداد قفسهٔ خالی تقسیم بر بازرسی",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    },
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است",
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "سفارش‌گذاری روزانه از مرکز توزیع"
  ]
}

