پوشش موجودی دسته‌های اصلی را گزارش کن؛ کجا ریسک داریم؟ (مدیر موجودی — یاس فروشگاه‌ها)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "stock_levels",
      "description": "موجودی به تفکیک دستهٔ کالا و شعبه",
      "dimensions": [
        "category",
        "branch"
      ],
      "measures": [
        "stock_m",
        "daily_sales_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_cover",
      "description": "پوشش موجودی",
      "formula": "موجودی تقسیم بر فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز و انبار شعبه",
    "انقضا با آستانهٔ هشدار سی روز پایش می‌شود",
    "سیستم پیش‌بینی تقاضا برای دسته‌های اصلی فعال است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "stock_levels",
    "filters": {
      "period": "today"
    }
  }
}

